#!/usr/bin/env python3
"""A list command for Pilot (ADR 0010). Pilot writes one JSON run message on stdin and closes it; the program prints
JSON lines on stdout: here one list message, whose rows Pilot filters as you type. Python 3.9 stdlib only, as macOS's
/usr/bin/python3; a list must answer within 2 s."""
import json
import subprocess
import sys


def send(message):
    sys.stdout.write(json.dumps(message, ensure_ascii=False) + "\n")


def listening():
    # lsof -F writes one field per line: p<pid>, c<command>, n<address>; it lists TCP sockets in LISTEN state.
    result = subprocess.run(["/usr/sbin/lsof", "-nP", "-iTCP", "-sTCP:LISTEN", "-F", "pcn"],
                            capture_output=True, text=True, timeout=1.5)
    rows, seen, pid, command = [], set(), "", ""
    for line in result.stdout.splitlines():
        if line.startswith("p"):
            pid = line[1:]
        elif line.startswith("c"):
            command = line[1:]
        elif line.startswith("n"):
            address = line[1:]
            key = (pid, address)
            if key not in seen:
                seen.add(key)
                rows.append((command, pid, address))
    return rows


def items(run):
    try:
        found = listening()
    except (OSError, subprocess.SubprocessError):
        send({"type": "error", "text": "could not run lsof to list open ports"})
        return
    rows = []
    for command, pid, address in found:
        port = address.rsplit(":", 1)[-1]
        rows.append({"id": "%s-%s-%s" % (pid, port, address), "title": "Port %s" % port,
                     "subtitle": "%s (pid %s) on %s" % (command, pid, address),
                     "actions": [{"type": "copy", "text": port, "title": "Copy port"},
                                 {"type": "hud", "text": "%s listens on %s" % (command, address),
                                  "title": "Say it"}]})
    if not rows:
        send({"type": "list", "items": [{"id": "none", "title": "No open ports",
                                         "subtitle": "Nothing is listening for TCP connections"}]})
        return
    send({"type": "list", "items": rows})


def main():
    try:
        run = json.loads(sys.stdin.readline())
    except ValueError:
        send({"type": "error", "text": "got a run message it could not read"})
        return
    command = run.get("command")
    if command == "items":
        items(run)
    else:
        send({"type": "error", "text": "has no command %s" % command})


if __name__ == "__main__":
    main()
